import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Emaki Series 文档","description":"","frontmatter":{"layout":"home","hero":{"name":"Emaki Series","text":"Paper RPG 插件套件","tagline":"面向 Paper 1.21.8+ 与 Java 25 的 RPG 插件套件。按模块安装，按 YAML 配置，按 CoreLib 统一动作、GUI、物品来源和 PDC 数据。","actions":[{"theme":"brand","text":"快速开始","link":"/guide/getting-started"},{"theme":"alt","text":"架构总览","link":"/guide/architecture"}]},"features":[{"title":"先确认 CoreLib","details":"所有业务模块都依赖 CoreLib。先理解动作、GUI、物品来源、PDC、表达式和经济桥接，再改业务配置。","link":"/modules/corelib/"},{"title":"属性先落到 PDC","details":"Attribute 负责属性定义、资源、伤害类型和条件。装备属性建议写入 PDC，不要只依赖 Lore 文本。","link":"/modules/attribute/"},{"title":"装备按层叠加","details":"Item、Forge、Strengthen、Gem 分别写入基础物品、锻造层、强化层和宝石层，Accessory 提供独立饰品栏，CoreLib 负责重建展示。","link":"/modules/forge/"},{"title":"成长与生产分开读","details":"Level 管多类型经验；Skills 管触发、冷却和资源消耗；Station 管通用合成与队列；Cooking 管世界工位和坐标状态。","link":"/modules/level/"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":0}`),a={name:`index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emaki-series-文档" tabindex="-1">Emaki Series 文档 <a class="header-anchor" href="#emaki-series-文档" aria-label="Permalink to “Emaki Series 文档”">​</a></h1><p>Emaki Series 是一组可组合安装的 Paper RPG 插件。它把物品、属性、成长、技能、图鉴、世界工位和自定义生物拆成独立模块，用 CoreLib 统一动作、GUI、物品来源、PDC 和展示重建。当前源码按 14 组 runtime/API 模块组织；你可以只启用需要的模块，也可以组合成完整 RPG 玩法链。</p><h2 id="推荐阅读路径" tabindex="-1">推荐阅读路径 <a class="header-anchor" href="#推荐阅读路径" aria-label="Permalink to “推荐阅读路径”">​</a></h2><ol><li>先读 <a href="/Emaki_Series/guide/introduction.html">项目介绍</a>，确认要安装哪些模块。</li><li>再读 <a href="/Emaki_Series/guide/getting-started.html">快速开始</a>，完成构建、安装和首次启动。</li><li>写 YAML 前，先读 <a href="/Emaki_Series/modules/corelib/">CoreLib</a> 的物品来源、动作、条件、表达式和 GUI。</li><li>做装备成长时，按 Attribute → Item → Forge / Strengthen / Gem / Accessory 的顺序阅读。</li><li>做成长与玩法系统时，分别阅读 Level、Skills、Station、Cooking、Codex 与 Storage。它们解决的问题不同。</li><li>做二次开发时，重点看 CoreLib 的 PDC、Assembly，以及各业务模块自己的 API（如 <code>emaki-attribute-api</code>、<code>emaki-item-api</code>、<code>emaki-level-api</code>）。</li></ol><h2 id="模块总览" tabindex="-1">模块总览 <a class="header-anchor" href="#模块总览" aria-label="Permalink to “模块总览”">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>角色</th><th>适合解决的问题</th></tr></thead><tbody><tr><td><a href="/Emaki_Series/modules/corelib/">EmakiCoreLib</a></td><td>公共基础设施</td><td>先读这里：动作、GUI、物品来源、PDC、表达式、经济、结构化展示。</td></tr><tr><td><a href="/Emaki_Series/modules/attribute/">EmakiAttribute</a></td><td>属性与战斗</td><td>定义属性、资源、伤害类型和条件，并给其他模块提供属性 API。</td></tr><tr><td><a href="/Emaki_Series/modules/item/">EmakiItem</a></td><td>自定义物品</td><td>生成稳定物品 ID，提供物品包/物品浏览 GUI，并写入基础属性、技能、套装和触发器。</td></tr><tr><td><a href="/Emaki_Series/modules/forge/">EmakiForge</a></td><td>锻造</td><td>用图纸和材料改造装备或生成新装备，计算品质和材料贡献。</td></tr><tr><td><a href="/Emaki_Series/modules/strengthen/">EmakiStrengthen</a></td><td>强化</td><td>按星级处理成功率、材料、失败惩罚、保护材料和强化展示。</td></tr><tr><td><a href="/Emaki_Series/modules/gem/">EmakiGem</a></td><td>宝石</td><td>管理插槽、开孔、镶嵌、提取、升级和宝石共鸣。</td></tr><tr><td><a href="/Emaki_Series/modules/accessory/">EmakiAccessory</a></td><td>饰品栏</td><td>提供多页隔离的饰品槽位、启用页切换、孤儿槽取回、属性/技能贡献和饰品套装。</td></tr><tr><td><a href="/Emaki_Series/modules/level/">EmakiLevel</a></td><td>等级成长</td><td>管理多等级类型、经验来源、升级需求、PDC、Placeholder 和 MythicMobs 经验 Drop。</td></tr><tr><td><a href="/Emaki_Series/modules/skills/">EmakiSkills</a></td><td>技能</td><td>管理主动/被动触发、冷却、资源消耗和 MythicMobs 调用。</td></tr><tr><td><a href="/Emaki_Series/modules/station/">EmakiStation</a></td><td>合成工作站</td><td>三页式通用合成站，串行队列、背包与仓库合并取材、付费队列位，并含独立的物品分解站。</td></tr><tr><td><a href="/Emaki_Series/modules/cooking/">EmakiCooking</a></td><td>烹饪工位</td><td>管理砧板、炒锅、研磨机、蒸锅、烤炉、榨汁机和发酵桶。</td></tr><tr><td><a href="/Emaki_Series/modules/codex/">EmakiCodex</a></td><td>图鉴与成就</td><td>同时定义原版成就页与分类条目图鉴 GUI，支持解锁、激活、领取、奖励、命令、CoreLib 动作和 API。</td></tr><tr><td><a href="/Emaki_Series/modules/storage/">EmakiStorage</a></td><td>GUI 仓库</td><td>单槽存放 <code>long</code> 量级数量并完整保留原始物品，容量由配置、权限、命令授予与付费扩容四来源决定，支持搜索与排序。</td></tr><tr><td><a href="/Emaki_Series/modules/mobs/">EmakiMobs</a></td><td>自定义生物</td><td>定义生物、刷新规则、掉落表和技能行为，并接入属性、技能与物品模块。</td></tr></tbody></table>`,6)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};